document.addEventListener('DOMContentLoaded',()=>{
 for(const context of ['create','edit']){
  const modal=document.getElementById(context==='create'?'createProductModal':'editProductModal'),editor=modal?.querySelector('.bundle-editor');if(!editor)continue;
  const type=modal.querySelector(context==='create'?'#create_product_type':'#edit_product_type'),rows=editor.querySelector('.bundle-editor-rows'),feedback=editor.querySelector('.bundle-editor-feedback'),summary=editor.querySelector('.bundle-editor-summary');let products=[],sequence=0,serial=0;
  function update(){let normal=0,cost=0,incomplete=false;rows.querySelectorAll('.bundle-row').forEach(row=>{const product=products.find(p=>String(p.id)===row.querySelector('select').value),quantity=Number(row.querySelector('[data-quantity]').value)||0;if(product){normal+=Number(product.price)*quantity;cost+=Number(product.estimated_cost)*quantity;incomplete=incomplete||product.cost_incomplete;}});const price=Number(modal.querySelector(context==='create'?'#create_prod_price':'#edit_prod_price')?.value)||0;summary.textContent='Regular items: ₱'+normal.toFixed(2)+' · Estimated cost: ₱'+cost.toFixed(2)+' · Package price: ₱'+price.toFixed(2)+' · Estimated gross profit: ₱'+(price-cost).toFixed(2)+(incomplete?' · Some costs use estimates.':'');}
  function row(value={}){const index=sequence++,node=document.createElement('div');node.className='bundle-row';node.innerHTML='<label>Included product<select name="package_items['+index+'][item_product_id]" class="form-select" required></select></label><label>Quantity<input type="number" name="package_items['+index+'][quantity]" data-quantity min="1" max="1000" step="1" class="form-control" required></label><label>Preparation station<input name="package_items['+index+'][station]" class="form-control" maxlength="80" required></label><button type="button" class="bundle-remove" aria-label="Remove package item">×</button>';const select=node.querySelector('select');select.add(new Option('Select a product',''));products.forEach(p=>select.add(new Option(p.name+' · '+(p.branch_name||'Shared'),p.id)));select.value=value.item_product_id||'';node.querySelector('[data-quantity]').value=Number(value.quantity)||1;node.querySelector('[maxlength]').value=value.station||'General';node.querySelector('button').onclick=()=>{node.remove();update();};node.addEventListener('input',update);node.addEventListener('change',update);rows.append(node);update();}
  async function load(){const generation=++serial,enabled=type.value==='combo';modal.querySelectorAll('.bundle-tab-switch').forEach(tab=>tab.classList.toggle('d-none',!enabled));editor.querySelectorAll('input,select,button').forEach(input=>input.disabled=!enabled);if(!enabled){const field=modal.querySelector(context==='create'?'[name="stock"]':'#edit_prod_stock');if(field&&type.value!=='recipe')field.readOnly=false;return;}
   const stock=modal.querySelector(context==='create'?'[name="stock"]':'#edit_prod_stock');if(stock){stock.value='0';stock.readOnly=true;}
   feedback.textContent='Loading package items…';rows.replaceChildren();products=[];
   const chosen=Array.from(modal.querySelectorAll('[name="branch_ids[]"]:checked'),input=>input.value);let branch=context==='create'?(chosen.length>1?'global':chosen[0]||modal.querySelector('[name="branch_id"]')?.value||''):modal.querySelector('#edit_prod_branch')?.value||'global';
   const data=new FormData();data.set('action','get_bundle_config');data.set('csrf_token',document.querySelector('meta[name="csrf-token"]')?.content||modal.querySelector('[name="csrf_token"]').value);data.set('branch_id',branch);data.set('product_id',context==='edit'?modal.querySelector('#edit_product_id').value:'0');
   try{const response=await fetch('?route=ajax/inventory_action',{method:'POST',credentials:'same-origin',body:data}),result=await response.json();if(generation!==serial)return;if(!response.ok||!result.success)throw new Error(result.message||'Could not load package items.');products=result.products;feedback.textContent=products.length?'':'No compatible sellable products are available. Choose a branch first or create component products.';const items=result.items||[];(items.length?items:[{}]).forEach(row);}catch(error){if(generation===serial)feedback.textContent=error.message;}
  }
  type.addEventListener('change',load);modal.querySelectorAll('[name="branch_ids[]"],#edit_prod_branch').forEach(field=>field.addEventListener('change',load));modal.querySelector(context==='create'?'#create_prod_price':'#edit_prod_price')?.addEventListener('input',update);editor.querySelector('.bundle-add-item').onclick=()=>row();jQuery(modal).on('shown.bs.modal',load);
  modal.querySelector('form').addEventListener('submit',event=>{if(type.value==='combo'&&!rows.querySelector('.bundle-row')){event.preventDefault();feedback.textContent='Add at least one package item.';bootstrap.Tab.getOrCreateInstance(modal.querySelector('[data-bs-target="#'+context+'-bundle-tab"]')).show();}if(type.value!=='combo')editor.querySelectorAll('input,select').forEach(field=>field.disabled=true);});
 }
});
